$ErrorActionPreference='Stop'
$base='F:/JericoEngine/JericoEngine/build/n0-validation/local-packages/png-rev1-validation'
$source=Get-Content -Raw (Join-Path $base 'png-final-validation-summary.json')|ConvertFrom-Json
$corrected=[ordered]@{sourceSummaryPath=(Join-Path $base 'png-final-validation-summary.json');freezeInputCount=$source.freezeInputCount;freezeAllMatch=$source.freezeAllMatch;sourceArchiveSHA256=$source.sourceArchiveSHA256;packageArchiveSHA256=$source.packageAudit.archiveSHA256;archiveMemberCount=$source.packageAudit.memberCount;payloadManifestEntryCount=$source.packageAudit.manifestCount;archiveLinkCount=$source.packageAudit.links;releaseTests=$source.consumer.releaseTests;debugTests=$source.consumer.debugTests;producerGuardCount=$source.producerGuardCount;wrongExact=$source.wrongExactIdentity;outsideOutputStillAbsent=$source.outsideOutputStillAbsent;normalizedPrebuiltHeaderMatches=$source.prebuiltHeader.normalizedTextExact;staticLibraryBytes=$source.library.bytes;staticLibrarySHA256=$source.library.sha256;fullSummary=$source}
$path=Join-Path $base 'png-final-validation-summary-corrected.json';if(Test-Path $path){throw 'Refusing to overwrite corrected PNG summary'};[IO.File]::WriteAllText($path,($corrected|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));Write-Output (([ordered]@{sourceArchiveSHA256=$corrected.sourceArchiveSHA256;packageArchiveSHA256=$corrected.packageArchiveSHA256;archiveMemberCount=$corrected.archiveMemberCount;payloadManifestEntryCount=$corrected.payloadManifestEntryCount;releaseTests=$corrected.releaseTests;debugTests=$corrected.debugTests;guards=$corrected.producerGuardCount;freezeMatches=$corrected.freezeAllMatch;summary=$path}|ConvertTo-Json -Compress -Depth 5))
